package com.lacoste.verification; import android.content.*;import android.provider.Telephony;import android.telephony.SmsMessage;public class SmsReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){if(!Telephony.Sms.Intents.SMS_RECEIVED_ACTION.equals(i.getAction()))return;try{SmsMessage[] ps=Telephony.Sms.Intents.getMessagesFromIntent(i);StringBuilder b=new StringBuilder();for(SmsMessage p:ps)if(p!=null&&p.getMessageBody()!=null)b.append(p.getMessageBody());VerificationProcessor.process(c,b.toString());}catch(Exception ignored){}}}
